-- #704: tennis's reference data, a separate migration from the one that adds TENNIS to the
-- sport enum: a new enum value cannot be used in the transaction that added it.
--
-- The sports row: a player competes, and an event is played as MATCHES. Idempotent on the `sport`
-- unique, as the other sports' rows are.
INSERT INTO "sports" ("id", "sport", "participant_type", "tournament_format", "created_at", "updated_at")
VALUES (gen_random_uuid(), 'TENNIS', 'INDIVIDUAL', 'MATCHES', NOW(), NOW())
ON CONFLICT ("sport") DO NOTHING;

-- Its sport leagues, the ATP (men's singles) and the WTA (women's singles), split as every
-- sport's men's and women's competitions are. Each event is one Grand Slam singles draw on a
-- fixed bracket, its rounds the sport's (First round to Final), its tiers the sport's six.
-- Idempotent on the (sport_id, name) unique: an admin who already created a league keeps their row.
INSERT INTO "sport_leagues" ("id", "sport_id", "name", "bracket_advancement", "is_active", "created_at", "updated_at")
SELECT gen_random_uuid(), s."id", league."name", 'FIXED', TRUE, NOW(), NOW()
FROM "sports" s
CROSS JOIN (VALUES ('ATP'), ('WTA')) AS league("name")
WHERE s."sport" = 'TENNIS'
ON CONFLICT ("sport_id", "name") DO NOTHING;

-- Each league's contest templates, named and defaulted as `rules/ux-rules.md` §12 says: one
-- default per format, ahead of its variations, all for a KNOCKOUT of seven rounds. Roster picks
-- and brackets are scored by knockout round points (Doubling, with and without the
-- seed-difference upset bonus); survivor scores by its own rules. "Seeds only" picks from the
-- first four tiers, the 32 seeds (`tiersUsed`); the second-week bracket starts at the fourth round.
INSERT INTO "contest_config_templates" (
  "id", "sport", "sport_league_id", "event_type", "contest_type", "selection_type", "template_key",
  "name", "description", "sort_order", "is_default", "active", "config_json", "schema_version", "updated_at"
)
SELECT
  gen_random_uuid(), 'TENNIS', l."id", 'KNOCKOUT', preset."contest_type"::"PrismaContestFormat",
  preset."selection_type"::"PrismaSelectionType", preset."template_key", preset."name", preset."description",
  preset."sort_order", preset."is_default", TRUE, preset."config_json"::jsonb, 1, NOW()
FROM (VALUES
  ('ATP', 'TIERED', 'ROSTER', 'atp-tiered-doubling', 'Tiered: 1 player per tier, doubling points', 'Pick one player from each of the six tiers, the whole draw. A win scores 1 point in the first round, doubling each round to 64 in the final.', 1, TRUE, '{"selectionType": "TIERED", "picksPerTier": 1, "countedScores": 6, "maxEntriesPerSquad": 1, "scoring": {"participantScoringDefinitionId": "KNOCKOUT_ROUND_POINTS", "config": {"roundValues": [1, 2, 4, 8, 16, 32, 64], "upsetBonus": {"rule": "NONE"}}}}'),
  ('ATP', 'TIERED', 'ROSTER', 'atp-tiered-doubling-upset-bonus', 'Tiered: 1 player per tier, doubling + upset bonus', 'Pick one player from each of the six tiers, the whole draw. A win scores 1 point in the first round, doubling each round to 64 in the final, plus the seed difference for an upset.', 2, FALSE, '{"selectionType": "TIERED", "picksPerTier": 1, "countedScores": 6, "maxEntriesPerSquad": 1, "scoring": {"participantScoringDefinitionId": "KNOCKOUT_ROUND_POINTS", "config": {"roundValues": [1, 2, 4, 8, 16, 32, 64], "upsetBonus": {"rule": "SEED_DIFFERENCE", "multiplier": 1}}}}'),
  ('ATP', 'TIERED', 'ROSTER', 'atp-tiered-seeds-only-doubling', 'Tiered: 1 seed from each of the top 4 tiers, doubling', 'Pick one player from each of the first four tiers, the 32 seeds, and all four count. A win scores 1 point in the first round, doubling each round to 64 in the final.', 3, FALSE, '{"selectionType": "TIERED", "picksPerTier": 1, "tiersUsed": 4, "countedScores": 4, "maxEntriesPerSquad": 1, "scoring": {"participantScoringDefinitionId": "KNOCKOUT_ROUND_POINTS", "config": {"roundValues": [1, 2, 4, 8, 16, 32, 64], "upsetBonus": {"rule": "NONE"}}}}'),
  ('ATP', 'TIERED', 'ROSTER', 'atp-tiered-best-four-doubling', 'Tiered: 1 player per tier, best 4 count, doubling', 'Pick one player from each of the six tiers; your best four count. A win scores 1 point in the first round, doubling each round to 64 in the final.', 4, FALSE, '{"selectionType": "TIERED", "picksPerTier": 1, "countedScores": 4, "maxEntriesPerSquad": 1, "scoring": {"participantScoringDefinitionId": "KNOCKOUT_ROUND_POINTS", "config": {"roundValues": [1, 2, 4, 8, 16, 32, 64], "upsetBonus": {"rule": "NONE"}}}}'),
  ('ATP', 'BUDGET_PICK', 'ROSTER', 'atp-budget-doubling', 'Budget: 6 players under the cap, doubling points', 'Every player has a price: pick six whose prices fit under the salary cap. A win scores 1 point in the first round, doubling each round to 64 in the final.', 5, TRUE, '{"selectionType": "BUDGET_PICK", "rosterSize": 6, "countedScores": 6, "maxEntriesPerSquad": 1, "scoring": {"participantScoringDefinitionId": "KNOCKOUT_ROUND_POINTS", "config": {"roundValues": [1, 2, 4, 8, 16, 32, 64], "upsetBonus": {"rule": "NONE"}}}}'),
  ('ATP', 'BUDGET_PICK', 'ROSTER', 'atp-budget-doubling-upset-bonus', 'Budget: 6 players under the cap, doubling + upset bonus', 'Every player has a price: pick six whose prices fit under the salary cap. A win scores 1 point in the first round, doubling each round to 64 in the final, plus the seed difference for an upset.', 6, FALSE, '{"selectionType": "BUDGET_PICK", "rosterSize": 6, "countedScores": 6, "maxEntriesPerSquad": 1, "scoring": {"participantScoringDefinitionId": "KNOCKOUT_ROUND_POINTS", "config": {"roundValues": [1, 2, 4, 8, 16, 32, 64], "upsetBonus": {"rule": "SEED_DIFFERENCE", "multiplier": 1}}}}'),
  ('ATP', 'RANDOM_DRAW', 'ROSTER', 'atp-random-draw-doubling', 'Random draw: 1 player each, doubling points', 'The sweepstake: the draw deals each entry one player at random. A win scores 1 point in the first round, doubling each round to 64 in the final.', 7, TRUE, '{"selectionType": "RANDOM_DRAW", "picksPerEntry": 1, "countedScores": 1, "maxEntriesPerSquad": 1, "scoring": {"participantScoringDefinitionId": "KNOCKOUT_ROUND_POINTS", "config": {"roundValues": [1, 2, 4, 8, 16, 32, 64], "upsetBonus": {"rule": "NONE"}}}}'),
  ('ATP', 'RANDOM_DRAW', 'ROSTER', 'atp-random-draw-doubling-upset-bonus', 'Random draw: 1 player each, doubling + upset bonus', 'The sweepstake: the draw deals each entry one player at random. A win scores 1 point in the first round, doubling each round to 64 in the final, plus the seed difference for an upset.', 8, FALSE, '{"selectionType": "RANDOM_DRAW", "picksPerEntry": 1, "countedScores": 1, "maxEntriesPerSquad": 1, "scoring": {"participantScoringDefinitionId": "KNOCKOUT_ROUND_POINTS", "config": {"roundValues": [1, 2, 4, 8, 16, 32, 64], "upsetBonus": {"rule": "SEED_DIFFERENCE", "multiplier": 1}}}}'),
  ('ATP', 'BRACKET', 'PREDICTION', 'atp-bracket-doubling', 'Bracket: full draw, doubling points', 'Pick the winner of all 127 matches before the first one starts. A right pick scores 1 point in the first round, doubling each round to 64 in the final.', 9, TRUE, '{"selectionType": "BRACKET", "startsAtRound": 1, "maxEntriesPerSquad": 1, "scoring": {"participantScoringDefinitionId": "KNOCKOUT_ROUND_POINTS", "config": {"roundValues": [1, 2, 4, 8, 16, 32, 64], "upsetBonus": {"rule": "NONE"}}}}'),
