  ('ATP', 'BRACKET', 'PREDICTION', 'atp-bracket-second-week-doubling', 'Bracket: second week, doubling points', 'A fresh bracket once the third round is played: pick the 15 matches from the fourth round on. A right pick scores its rounds points, doubling each round.', 11, FALSE, '{"selectionType": "BRACKET", "startsAtRound": 4, "maxEntriesPerSquad": 1, "scoring": {"participantScoringDefinitionId": "KNOCKOUT_ROUND_POINTS", "config": {"roundValues": [1, 2, 4, 8, 16, 32, 64], "upsetBonus": {"rule": "NONE"}}}}'),
