  ('WTA', 'TIERED', 'ROSTER', 'wta-tiered-doubling-upset-bonus', 'Tiered: 1 player per tier, doubling + upset bonus', 'Pick one player from each of the six tiers, the whole draw. A win scores 1 point in the first round, doubling each round to 64 in the final, plus the seed difference for an upset.', 2, FALSE, '{"selectionType": "TIERED", "picksPerTier": 1, "countedScores": 6, "maxEntriesPerSquad": 1, "scoring": {"participantScoringDefinitionId": "KNOCKOUT_ROUND_POINTS", "config": {"roundValues": [1, 2, 4, 8, 16, 32, 64], "upsetBonus": {"rule": "SEED_DIFFERENCE", "multiplier": 1}}}}'),
