-- The Slams pool (as golf's majors pool, #714): one tiered contest over a year's four Grand
-- Slams in one league, taking each Slam's draw as it is released. A variation, not a default.
INSERT INTO "contest_config_templates" (
  "id", "sport", "sport_league_id", "event_type", "contest_type", "selection_type", "template_key",
  "name", "description", "sort_order", "is_default", "active", "config_json", "schema_version", "event_series_names", "updated_at"
)
SELECT
  gen_random_uuid(), 'TENNIS', l."id", 'KNOCKOUT', 'ROSTER', 'TIERED', preset."template_key", preset."name",
  preset."description", preset."sort_order", FALSE, TRUE, preset."config_json"::jsonb, 1,
  ARRAY['Australian Open', 'Roland Garros', 'Wimbledon', 'US Open'], NOW()
FROM (VALUES
  ('ATP', 'atp-slams-tiered-doubling', 'Tiered Slams pool: 1 player per tier, doubling points', 'One contest across the four Grand Slams, picking one player from each tier at each. A win scores 1 point in the first round, doubling each round to 64 in the final.', 13, '{"selectionType": "TIERED", "picksPerTier": 1, "countedScores": 6, "maxEntriesPerSquad": 1, "scoring": {"participantScoringDefinitionId": "KNOCKOUT_ROUND_POINTS", "config": {"roundValues": [1, 2, 4, 8, 16, 32, 64], "upsetBonus": {"rule": "NONE"}}}}'),
  ('WTA', 'wta-slams-tiered-doubling', 'Tiered Slams pool: 1 player per tier, doubling points', 'One contest across the four Grand Slams, picking one player from each tier at each. A win scores 1 point in the first round, doubling each round to 64 in the final.', 13, '{"selectionType": "TIERED", "picksPerTier": 1, "countedScores": 6, "maxEntriesPerSquad": 1, "scoring": {"participantScoringDefinitionId": "KNOCKOUT_ROUND_POINTS", "config": {"roundValues": [1, 2, 4, 8, 16, 32, 64], "upsetBonus": {"rule": "NONE"}}}}')
) AS preset("league", "template_key", "name", "description", "sort_order", "config_json")
JOIN "sports" s ON s."sport" = 'TENNIS'
JOIN "sport_leagues" l ON l."sport_id" = s."id" AND l."name" = preset."league"
ON CONFLICT ("sport", "event_type", "contest_type", "selection_type", "template_key") DO NOTHING;
